```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* head = NULL;

// Function prototypes
void createList();
void display();
void insertAtBeginning();
void insertAtEnd();
void insertAtPosition();
void deleteAtBeginning();
void deleteAtEnd();
void deleteAtPosition();
void deleteByValue();
void search();
void update();
void reverse();
void sort();
void findMaxMin();
void findMiddle();
void detectLoop();
void deleteAll();

int countNodes();

int main() {
    int choice;
    while (1) {
        printf("\n\n====== Singly Linked List Menu ======\n");
        printf("1. Create List\n2. Display\n3. Count Nodes\n4. Insert at Beginning\n5. Insert at End\n");
        printf("6. Insert at Position\n7. Delete at Beginning\n8. Delete at End\n9. Delete at Position\n10. Delete by Value\n");
        printf("11. Search\n12. Update\n13. Reverse\n14. Sort (Ascending)\n15. Find Max/Min\n16. Find Middle\n17. Detect Loop\n18. Delete All\n19. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1: createList(); break;
            case 2: display(); break;
            case 3: printf("Total nodes: %d\n", countNodes()); break;
            case 4: insertAtBeginning(); break;
            case 5: insertAtEnd(); break;
            case 6: insertAtPosition(); break;
            case 7: deleteAtBeginning(); break;
            case 8: deleteAtEnd(); break;
            case 9: deleteAtPosition(); break;
            case 10: deleteByValue(); break;
            case 11: search(); break;
            case 12: update(); break;
            case 13: reverse(); break;
            case 14: sort(); break;
            case 15: findMaxMin(); break;
            case 16: findMiddle(); break;
            case 17: detectLoop(); break;
            case 18: deleteAll(); break;
            case 19: exit(0);
            default: printf("Invalid choice!\n");
        }
    }
    return 0;
}

void createList() {
    int n, data;
    printf("Enter number of nodes: ");
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        printf("Enter data: ");
        scanf("%d", &data);
        insertAtEnd(data);
    }
}

void display() {
    struct Node* temp = head;
    if (!temp) {
        printf("List is empty.\n");
        return;
    }
    printf("Linked List: ");
    while (temp) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

int countNodes() {
    int count = 0;
    struct Node* temp = head;
    while (temp) {
        count++;
        temp = temp->next;
    }
    return count;
}

void insertAtBeginning() {
    int data;
    printf("Enter data: ");
    scanf("%d", &data);
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
}

void insertAtEnd(int dataOptional) {
    int data;
    if (dataOptional == -1) {
        printf("Enter data: ");
        scanf("%d", &data);
    } else data = dataOptional;

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;

    if (!head) {
        head = newNode;
        return;
    }

    struct Node* temp = head;
    while (temp->next)
        temp = temp->next;
    temp->next = newNode;
}

void insertAtPosition() {
    int pos, data;
    printf("Enter position and data: ");
    scanf("%d %d", &pos, &data);

    if (pos < 1 || pos > countNodes() + 1) {
        printf("Invalid position!\n");
        return;
    }
    if (pos == 1) { insertAtBeginning(); return; }

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    struct Node* temp = head;

    for (int i = 1; i < pos - 1; i++)
        temp = temp->next;

    newNode->next = temp->next;
    temp->next = newNode;
}

void deleteAtBeginning() {
    if (!head) { printf("List empty.\n"); return; }
    struct Node* temp = head;
    head = head->next;
    free(temp);
}

void deleteAtEnd() {
    if (!head) { printf("List empty.\n"); return; }
    if (!head->next) { free(head); head = NULL; return; }

    struct Node* temp = head;
    while (temp->next->next)
        temp = temp->next;
    free(temp->next);
    temp->next = NULL;
}

void deleteAtPosition() {
    int pos;
    printf("Enter position to delete: ");
    scanf("%d", &pos);
    if (pos < 1 || pos > countNodes()) {
        printf("Invalid position!\n");
        return;
    }
    if (pos == 1) { deleteAtBeginning(); return; }

    struct Node* temp = head;
    for (int i = 1; i < pos - 1; i++)
        temp = temp->next;
    struct Node* del = temp->next;
    temp->next = del->next;
    free(del);
}

void deleteByValue() {
    int val;
    printf("Enter value to delete: ");
    scanf("%d", &val);

    if (!head) return;
    if (head->data == val) { deleteAtBeginning(); return; }

    struct Node* temp = head;
    while (temp->next && temp->next->data != val)
        temp = temp->next;

    if (temp->next) {
        struct Node* del = temp->next;
        temp->next = del->next;
        free(del);
    } else printf("Value not found!\n");
}

void search() {
    int val, pos = 1, found = 0;
    printf("Enter value to search: ");
    scanf("%d", &val);

    struct Node* temp = head;
    while (temp) {
        if (temp->data == val) {
            printf("Value found at position %d\n", pos);
            found = 1;
        }
        temp = temp->next;
        pos++;
    }
    if (!found) printf("Value not found.\n");
}

void update() {
    int oldVal, newVal;
    printf("Enter old value and new value: ");
    scanf("%d %d", &oldVal, &newVal);

    struct Node* temp = head;
    while (temp) {
        if (temp->data == oldVal)
            temp->data = newVal;
        temp = temp->next;
    }
    printf("Updated (if value found).\n");
}

void reverse() {
    struct Node *prev = NULL, *curr = head, *next = NULL;
    while (curr) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    head = prev;
    printf("List reversed.\n");
}

void sort() {
    if (!head) return;
    struct Node *i, *j;
    int temp;
    for (i = head; i->next; i = i->next) {
        for (j = i->next; j; j = j->next) {
            if (i->data > j->data) {
                temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
        }
    }
    printf("List sorted.\n");
}

void findMaxMin() {
    if (!head) return;
    int max = head->data, min = head->data;
    struct Node* temp = head->next;
    while (temp) {
        if (temp->data > max) max = temp->data;
        if (temp->data < min) min = temp->data;
        temp = temp->next;
    }
    printf("Max = %d, Min = %d\n", max, min);
}

void findMiddle() {
    struct Node *slow = head, *fast = head;
    if (!head) { printf("Empty list.\n"); return; }
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    printf("Middle element = %d\n", slow->data);
}

void detectLoop() {
    struct Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            printf("Loop detected!\n");
            return;
        }
    }
    printf("No loop found.\n");
}

void deleteAll() {
    struct Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
    printf("All nodes deleted.\n");
}
```

