## 🧩 Full Code — Modular Singly Linked List (C)

```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;
    struct Node* next;
};

// Function declarations
struct Node* createList(struct Node* head);
void display(struct Node* head);
int countNodes(struct Node* head);
struct Node* insertAtBeginning(struct Node* head, int data);
struct Node* insertAtEnd(struct Node* head, int data);
struct Node* insertAtPosition(struct Node* head, int data, int pos);
struct Node* deleteAtBeginning(struct Node* head);
struct Node* deleteAtEnd(struct Node* head);
struct Node* deleteAtPosition(struct Node* head, int pos);
struct Node* deleteByValue(struct Node* head, int val);
void search(struct Node* head, int val);
struct Node* update(struct Node* head, int oldVal, int newVal);
struct Node* reverse(struct Node* head);
struct Node* sort(struct Node* head);
void findMaxMin(struct Node* head);
void findMiddle(struct Node* head);
void detectLoop(struct Node* head);
struct Node* deleteAll(struct Node* head);

// Main menu
int main() {
    struct Node* head = NULL;
    int choice, data, pos, val, oldVal, newVal;

    while (1) {
        printf("\n======= Singly Linked List Menu =======\n");
        printf("1. Create List\n2. Display\n3. Count Nodes\n4. Insert at Beginning\n5. Insert at End\n");
        printf("6. Insert at Position\n7. Delete at Beginning\n8. Delete at End\n9. Delete at Position\n10. Delete by Value\n");
        printf("11. Search\n12. Update\n13. Reverse\n14. Sort\n15. Find Max/Min\n16. Find Middle\n17. Detect Loop\n18. Delete All\n19. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                head = createList(head);
                break;
            case 2:
                display(head);
                break;
            case 3:
                printf("Total nodes: %d\n", countNodes(head));
                break;
            case 4:
                printf("Enter data: ");
                scanf("%d", &data);
                head = insertAtBeginning(head, data);
                break;
            case 5:
                printf("Enter data: ");
                scanf("%d", &data);
                head = insertAtEnd(head, data);
                break;
            case 6:
                printf("Enter data and position: ");
                scanf("%d%d", &data, &pos);
                head = insertAtPosition(head, data, pos);
                break;
            case 7:
                head = deleteAtBeginning(head);
                break;
            case 8:
                head = deleteAtEnd(head);
                break;
            case 9:
                printf("Enter position to delete: ");
                scanf("%d", &pos);
                head = deleteAtPosition(head, pos);
                break;
            case 10:
                printf("Enter value to delete: ");
                scanf("%d", &val);
                head = deleteByValue(head, val);
                break;
            case 11:
                printf("Enter value to search: ");
                scanf("%d", &val);
                search(head, val);
                break;
            case 12:
                printf("Enter old value and new value: ");
                scanf("%d%d", &oldVal, &newVal);
                head = update(head, oldVal, newVal);
                break;
            case 13:
                head = reverse(head);
                break;
            case 14:
                head = sort(head);
                break;
            case 15:
                findMaxMin(head);
                break;
            case 16:
                findMiddle(head);
                break;
            case 17:
                detectLoop(head);
                break;
            case 18:
                head = deleteAll(head);
                break;
            case 19:
                exit(0);
            default:
                printf("Invalid choice!\n");
        }
    }
    return 0;
}

// Function definitions
struct Node* createList(struct Node* head) {
    int n, data;
    printf("Enter number of nodes: ");
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        printf("Enter data for node %d: ", i + 1);
        scanf("%d", &data);
        head = insertAtEnd(head, data);
    }
    return head;
}

void display(struct Node* head) {
    if (!head) {
        printf("List is empty.\n");
        return;
    }
    printf("List: ");
    struct Node* temp = head;
    while (temp) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

int countNodes(struct Node* head) {
    int count = 0;
    while (head) {
        count++;
        head = head->next;
    }
    return count;
}

struct Node* insertAtBeginning(struct Node* head, int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = head;
    return newNode;
}

struct Node* insertAtEnd(struct Node* head, int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;

    if (!head) return newNode;

    struct Node* temp = head;
    while (temp->next)
        temp = temp->next;
    temp->next = newNode;
    return head;
}

struct Node* insertAtPosition(struct Node* head, int data, int pos) {
    if (pos < 1) {
        printf("Invalid position!\n");
        return head;
    }
    if (pos == 1)
        return insertAtBeginning(head, data);

    struct Node* temp = head;
    for (int i = 1; i < pos - 1 && temp; i++)
        temp = temp->next;

    if (!temp) {
        printf("Position out of range!\n");
        return head;
    }

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = temp->next;
    temp->next = newNode;

    return head;
}

struct Node* deleteAtBeginning(struct Node* head) {
    if (!head) {
        printf("List empty.\n");
        return NULL;
    }
    struct Node* temp = head;
    head = head->next;
    free(temp);
    return head;
}

struct Node* deleteAtEnd(struct Node* head) {
    if (!head) return NULL;
    if (!head->next) {
        free(head);
        return NULL;
    }
    struct Node* temp = head;
    while (temp->next->next)
        temp = temp->next;
    free(temp->next);
    temp->next = NULL;
    return head;
}

struct Node* deleteAtPosition(struct Node* head, int pos) {
    if (pos < 1 || !head) return head;
    if (pos == 1) return deleteAtBeginning(head);

    struct Node* temp = head;
    for (int i = 1; temp && i < pos - 1; i++)
        temp = temp->next;

    if (!temp || !temp->next) {
        printf("Position out of range!\n");
        return head;
    }

    struct Node* del = temp->next;
    temp->next = del->next;
    free(del);
    return head;
}

struct Node* deleteByValue(struct Node* head, int val) {
    if (!head) return NULL;
    if (head->data == val)
        return deleteAtBeginning(head);

    struct Node* temp = head;
    while (temp->next && temp->next->data != val)
        temp = temp->next;

    if (temp->next) {
        struct Node* del = temp->next;
        temp->next = del->next;
        free(del);
    } else printf("Value not found!\n");

    return head;
}

void search(struct Node* head, int val) {
    int pos = 1, found = 0;
    while (head) {
        if (head->data == val) {
            printf("Found at position %d\n", pos);
            found = 1;
        }
        head = head->next;
        pos++;
    }
    if (!found) printf("Value not found.\n");
}

struct Node* update(struct Node* head, int oldVal, int newVal) {
    struct Node* temp = head;
    while (temp) {
        if (temp->data == oldVal)
            temp->data = newVal;
        temp = temp->next;
    }
    return head;
}

struct Node* reverse(struct Node* head) {
    struct Node *prev = NULL, *curr = head, *next = NULL;
    while (curr) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    printf("List reversed.\n");
    return prev;
}

struct Node* sort(struct Node* head) {
    if (!head) return NULL;
    struct Node *i, *j;
    int temp;
    for (i = head; i->next; i = i->next)
        for (j = i->next; j; j = j->next)
            if (i->data > j->data) {
                temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
    printf("List sorted.\n");
    return head;
}

void findMaxMin(struct Node* head) {
    if (!head) return;
    int max = head->data, min = head->data;
    head = head->next;
    while (head) {
        if (head->data > max) max = head->data;
        if (head->data < min) min = head->data;
        head = head->next;
    }
    printf("Max: %d, Min: %d\n", max, min);
}

void findMiddle(struct Node* head) {
    struct Node *slow = head, *fast = head;
    if (!head) return;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    printf("Middle element: %d\n", slow->data);
}

void detectLoop(struct Node* head) {
    struct Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            printf("Loop detected!\n");
            return;
        }
    }
    printf("No loop found.\n");
}

struct Node* deleteAll(struct Node* head) {
    struct Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
    printf("All nodes deleted.\n");
    return NULL;
}
```

