## 🧠 Clean, Independent `createList()` Function
(Doesn’t use `insertAtEnd()`)

```c
struct Node* createList(struct Node* head) {
    int n, data;
    struct Node *newNode, *temp;

    printf("Enter number of nodes: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("List size must be positive.\n");
        return NULL;
    }

    head = NULL;

    for (int i = 0; i < n; i++) {
        printf("Enter data for node %d: ", i + 1);
        scanf("%d", &data);

        // Create new node
        newNode = (struct Node*)malloc(sizeof(struct Node));
        newNode->data = data;
        newNode->next = NULL;

        // If it's the first node
        if (head == NULL) {
            head = newNode;
            temp = head;
        } else {
            temp->next = newNode;
            temp = newNode;
        }
    }

    printf("List created successfully.\n");
    return head;
}
```

